	const wrappedJs = wrapPortableJsBundle(bundle.compiledJs);
	const indexHtml = buildPortableIndexHtml(target, dataJsonStr, connectionBootstrap);
	const readmeMd = buildPackageReadme(target);
	const commonEntries = [
		{
			path: "index.html",
			content: indexHtml
		},
		{
			path: "style.css",
			content: bundle.compiledCss
		},
		{
			path: "app.js",
			content: wrappedJs
		},
		{
			path: "fonts.css",
			content: bundle.fontsCss
		},
		{
			path: "data.json",
			content: dataJsonStr
		},
		{
			path: "logo.svg",
			content: bundle.logoSvg
		},
		{
			path: "favicon.svg",
			content: bundle.faviconSvg
		},
		{
			path: "README.md",
			content: readmeMd
		}
	];
